def min_transport_cost(c1, c2, c3, c4, n, m, a, b):
    # Calculate the total number of rides
    total_rides_buses = sum(a)
    total_rides_trolleys = sum(b)

    # Initialize the DP table
    dp = [[float('inf')] * (total_rides_trolleys + 1) for _ in range(total_rides_buses + 1)]

    # Base case: no rides, no cost
    dp[0][0] = 0

    # Fill the DP table
    for i in range(1, total_rides_buses + 1):
        for j in range(total_rides_trolleys + 1):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + c1)
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + c1)
            if i > 0 and j > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + c1)
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + c2)
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + c2)
            if i > 0 and j > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + c2)
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + c3)
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + c3)
            if i > 0 and j > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + c3)
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + c4)
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + c4)
            if i > 0 and j > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + c4)

    return dp[-1][-1]

