if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    c1 = int(data[0])
    c2 = int(data[1])
    c3 = int(data[2])
    c4 = int(data[3])
    n = int(data[4])
    m = int(data[5])
    a = list(map(int, data[6:6+n]))
    b = list(map(int, data[6+n:]))

    result = min_transport_cost(c1, c2, c3, c4, n, m, a, b)
    print(result)
